#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Room v3 (sudah termasuk pasang-room.sh & pasang-room-v2.sh sebelumnya):
#  - bar bawah mode on-mic disebar rata; speaker (tidak dengar orang) di samping mic (bicara)
#  - emoji = bubble di foto kursi selama 1,5 detik, terlihat semua orang di room (tidak masuk chat)
#  - ikon mic kursi kosong rata tengah
#  - kursi: frame + foto, nickname di bawah (owner pakai ikon rumah), kursi 1 owner = "Ambil Mic"
#  - chat kosong saat masuk room; chat baru: avatar kiri, badge role + nama kanan, isi chat di bawah
# Syarat: profil baru (pasang-profil.sh) & SVGA sudah terpasang.
# Jalankan di root repo:  bash pasang-room-v3.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
R="app/src/main/res"
[ -f "$D/ProfileTheme.kt" ] && [ -f "$D/FlowRow.kt" ] && [ -f "$D/SvgaStore.kt" ] || { echo "❌ Pasang dulu pasang-profil.sh dan SVGA (pasang-svga-firestore.sh)"; exit 1; }
T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"
BK="$HOME/.hayu-backup-room3-$(date +%H%M%S)"
FIXED=0
fix() {
  f="$1"; m="$2"
  if [ -f "$f" ] && grep -q -- "$m" "$f"; then
    echo "  ok         $f"
  else
    [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
    mkdir -p "$(dirname "$f")"
    cp "$T/new/$f" "$f"
    echo "  DIPERBAIKI $f"
    FIXED=$((FIXED+1))
  fi
}
fix $D/RoomActivity.kt               "sendEmojiReaction"
fix $D/ProfileTheme.kt               "compact: Boolean"
fix $D/adapter/RoomMessageAdapter.kt "T_USER"
fix $D/util/UserInfoCache.kt         "object UserInfoCache"
fix $R/layout/item_room_chat.xml     "chat_header"
fix $R/layout/activity_room.xml      "sp_pill"
fix $R/drawable/ic_mic_seat.xml      "pathData"
fix $R/drawable/ic_speaker_on.xml    "pathData"
fix $R/drawable/ic_speaker_off.xml   "pathData"
fix $R/drawable/ic_mic_on.xml        "pathData"
fix $R/drawable/ic_mic_off.xml       "pathData"
rm -rf "$T"
[ "$FIXED" -eq 0 ] && echo "✅ Sudah terpasang, tidak ada yang diubah." || echo "✅ $FIXED file dipasang (backup lama: $BK)"
if [ -d .git ] && [ "$FIXED" -gt 0 ]; then
  BR=$(git rev-parse --abbrev-ref HEAD)
  git add -A
  git commit -m "room v3: bar on-mic rata, speaker & mic terpisah, emoji bubble di kursi, ikon mic kursi rata tengah" \
    -m "$(printf 'Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01NoSA5bjZUeFkcabKTv65uQ')" || true
  git pull --rebase --autostash origin "$BR" || { echo "⚠️ Konflik saat pull, selesaikan lalu: git rebase --continue && git push origin $BR"; exit 1; }
  git push origin "$BR"
  echo "✅ Terkirim ke origin/$BR"
fi
